/// Like [`Self::push_arg_values`] but bypasses the user-provided (potentially
/// overridden) value parser in favor of the action's own default value parser.
///
/// This is used for the synthetic values (e.g. `"true"`/`"false"` for
/// `ArgAction::SetTrue`/`SetFalse`) that clap generates internally, rather than
/// values that came from the user on the command line.  Running an overridden value
/// parser (like [`UnknownArgumentValueParser`][crate::builder::UnknownArgumentValueParser])
/// against these synthetic values doesn't make sense and would eagerly error out even
/// when the argument was never used.
fn push_arg_values_with_action_parser(
    &self,
    arg: &Arg,
    raw_vals: Vec<OsString>,
    matcher: &mut ArgMatcher,
) -> ClapResult<()> {
    debug!("Parser::push_arg_values_with_action_parser: {raw_vals:?}");

    let value_parser = arg
        .get_action()
        .default_value_parser()
        .unwrap_or_else(|| arg.get_value_parser().clone());
    for raw_val in raw_vals {
        // update the current index because each value is a distinct index to clap
        self.cur_idx.set(self.cur_idx.get() + 1);
        debug!(
            "Parser::add_single_val_to_arg: cur_idx:={}",
            self.cur_idx.get()
        );
        let val = ok!(value_parser.parse_ref(self.cmd, Some(arg), &raw_val));

        matcher.add_val_to(arg.get_id(), val, raw_val);
        matcher.add_index_to(arg.get_id(), self.cur_idx.get());
    }

    Ok(())
}

